ssize_t socket_read(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    int err = 0;
    ssize_t ret = 0;

    if (sock->sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if (count > 0xFFFF)
        count = 0xFFFF;

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb) {
        if (file->f_flags & O_NONBLOCK)
            return -EAGAIN;

        wait_for_data(sock);
        skb = skb_dequeue(&sock->sk->sk_receive_queue);
        if (!skb)
            return -EAGAIN;
    }

    if (count > skb->len)
        count = skb->len;

    if (copy_to_user(buf, skb->data, count)) {
        err = -EFAULT;
        goto out;
    }

    ret = count;
    sock->sk->sk_data_processed += count;
    sock->sk->sk_forward_alloc = 0;
    sock->sk->sk_err = 0;

    sock_skb_free(skb);

out:
    return ret ? ret : err;
}

ssize_t socket_read(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    int copied = 0;
    ssize_t ret;

    if (sock->type == SOCK_STREAM && sock->ops->read == NULL)
        return -EAGAIN;

    if (count == 0)
        return 0;

    if (unlikely(!access_ok(buf, count)))
        return -EFAULT;

    skb = skb_peek(&sock->sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = min(skb->len, count);

    skb_lock(skb);
    if (skb->len < copied) {
        ret = -EFAULT;
        goto out;
    }

    if (copy_to_user(buf, skb->data, copied)) {
        ret = -EFAULT;
        goto out;
    }

    ret = copied;
    skb_unlink(skb, &sock->sk->sk_receive_queue);
    sock->sk->sk_backlog.len -= skb->truesize;
    kfree_skb(skb);

    return ret;

out:
    skb_unlock(skb);
    return ret;
}

ssize_t read_from_socket(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    int err;
    ssize_t bytes_read;

    if (sock->type & SOCK_NONBLOCK) {
        if (skb_queue_empty(&sock->sk->sk_receive_queue)) {
            return -EAGAIN;
        }
    }

    if (!access_ok(buf, count)) {
        return -EFAULT;
    }

    if (count == 0) {
        return 0;
    }

    if (count > MAX_RECEIVE_BUFFER_SIZE) {
        return -EINVAL;
    }

    while (skb_queue_empty(&sock->sk->sk_receive_queue)) {
        err = wait_for_data(sock);
        if (err < 0) {
            return err;
        }
    }

    spin_lock(&sock->sk->sk_receive_queue.lock);
    skb = skb_peek(&sock->sk->sk_receive_queue);
    if (!skb) {
        spin_unlock(&sock->sk->sk_receive_queue.lock);
        return -EFAULT;
    }

    bytes_read = min(count, (size_t)skb->len);
    err = copy_to_user(buf, skb->data, bytes_read);
    if (err) {
        spin_unlock(&sock->sk->sk_receive_queue.lock);
        return -EFAULT;
    }

    skb_unlink(skb, &sock->sk->sk_receive_queue);
    sock->sk->sk_receive_queue.qlen--;
    spin_unlock(&sock->sk->sk_receive_queue.lock);

    kfree_skb(skb);
    return bytes_read;
}

ssize_t read_from_socket(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sk_buff *skb;
    ssize_t bytes_read = 0;
    int err = 0;

    if (sock == NULL)
        return -EINVAL;

    if (count == 0)
        return 0;

    if (unlikely(!access_ok(buf, count)))
        return -EFAULT;

    skb = skb_peek(&sock->sk->sk_receive_queue);
    if (!skb) {
        if (file->f_flags & O_NONBLOCK)
            return -EAGAIN;

        err = wait_for_read_lock(sock);
        if (err < 0)
            return err;

        skb = skb_peek(&sock->sk->sk_receive_queue);
        if (!skb)
            return -EAGAIN;
    }

    bytes_read = min(skb->len, (int)count);
    if (copy_to_user(buf, skb->data, bytes_read)) {
        err = -EFAULT;
    } else {
        skb_pop(&sock->sk->sk_receive_queue, bytes_read);
    }

    sock_put_lock(sock->sk);

    if (err < 0)
        return err;

    return bytes_read;
}

ssize_t sock_read(struct file *file, char __user *buf, size_t count, loff_t *ppos)
{
    struct socket *sock = file->private_data;
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int err = 0;
    ssize_t copied = 0;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    if (file->f_flags & O_NONBLOCK) {
        if (skb_queue_empty(&sk->sk_receive_queue))
            return -EAGAIN;
    }

    if (!access_ok(buf, count))
        return -EFAULT;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = min(count, (size_t)skb->len);

    err = copy_to_user(buf, skb->data, copied);
    if (err) {
        err = -EFAULT;
        goto out;
    }

    sk->sk_data_processed += copied;
    sock_wake_async(sk, 0, 0);

out:
    kfree_skb(skb);
    return (err < 0) ? err : copied;
}
